import{_ as d,C as n,o as p,c,E as t,w as r,j as e,a}from"./chunks/framework.CWBU7zwD.js";const b=JSON.parse(`{"title":"","description":"","frontmatter":{"pageClass":"st-page-large","parcours":"PM","id":"QZ","titre":"Quiz « rôle inversé » : auditer une note de décision produite par l'IA","duree":20,"quiz":{"doc":[{"t":"title","x":"NOTE DE DÉCISION — Feuille de route de Lanterne, trimestre suivant"},{"t":"sub","x":"(rédigée par l'assistant IA pour la revue du portefeuille Séjour — chiffres fictifs)"},{"t":"p","x":"Décision demandée : valider la feuille de route ci-dessous, dont la généralisation du départ express à LIL-07 et NTE-02."},{"t":"h","x":"1. Marché"},{"t":"p","x":"Le Concurrent B a déployé la clé mobile dans tous ses hôtels.","d":"D1"},{"t":"p","x":"Source : communiqué de presse d'il y a 18 mois annonçant un projet."},{"t":"p","x":"Le Concurrent A propose déjà le règlement dans l'application (page d'aide, il y a 3 semaines)."},{"t":"h","x":"2. Ce que disent les clients"},{"t":"p","x":"Questionnaire après séjour : 60 réponses, dont 36 de LYS-03, surtout des séjours d'affaires."},{"t":"p","x":"Thème le plus cité : l'attente au comptoir (17 réponses)."},{"t":"p","x":"Les clients veulent avant tout le départ express : 17 réponses sur 60.","d":"D2"},{"t":"h","x":"3. Objectifs proposés (O4 — Rendre le départ fluide)"},{"t":"p","x":"KR4.1 : livrer le départ express sur les trois hôtels pilotes.","d":"D3"},{"t":"p","x":"KR4.2 : part des départs réglés dans l'application (départs express ÷ départs de l'hôtel, comptés par le PMS), par hôtel et par mois ; valeur de départ à LIL-07 et NTE-02 : non mesuré."},{"t":"h","x":"4. Business case de la généralisation"},{"t":"p","x":"Temps de réception libéré dans les deux hôtels : 47,6 h par mois dans le scénario médian (17 % de départs express)."},{"t":"p","x":"Gain : 47,6 h par mois × 25 € de l'heure × 12 = 14 280 € par an.","d":"D4"},{"t":"p","x":"Ce qu'on ne sait pas : coût horaire de la réception : non fourni ; frais du prestataire par transaction : non fournis."},{"t":"h","x":"5. Feuille de route proposée"},{"t":"p","x":"Capacité : 5 sprints pour les initiatives. L'équipe Amarre est disponible un seul sprint et ne peut prendre qu'un des deux sujets qui en dépendent (I4 ou I8)."},{"t":"p","x":"Sprint 1 : LAN-120 (sécurité de la vue réception), avant toute extension."},{"t":"p","x":"Sprint 2 : I4 et I8 avec l'équipe Amarre.","d":"D5"},{"t":"p","x":"Ensuite : généraliser le départ express à LIL-07, puis à NTE-02."},{"t":"p","x":"On arrête : l'ancien écran web « Départ », après avoir prévenu ses utilisateurs."},{"t":"h","x":"6. Résultats du pilote (4 semaines, LYS-03)"},{"t":"p","x":"Le pilote est un succès : 24 % de départs express.","d":"D6"},{"t":"p","x":"Détail : 574 départs express sur 3 365 départs ; semaine 1 : 9 %, semaine 4 : 24 %."},{"t":"p","x":"Litiges sur la note : de 1 à 5 par semaine ; frais facturés après le départ : de 3 à 9 par semaine."},{"t":"h","x":"7. Réponses aux objections"},{"t":"p","x":"Direction financière, « Combien ça rapporte ? » : voir le gain calculé en section 4.","d":"D4"},{"t":"p","x":"Direction des opérations : le départ tardif sera livré au prochain trimestre, sans risque.","d":"D7"},{"t":"p","x":"État de LAN-101 (départ tardif) : toujours à spécifier."},{"t":"h","x":"8. Comment cette note a été préparée"},{"t":"p","x":"Contexte fourni à l'IA : la fiche de contexte de l'an dernier, sans date de revue, et l'export complet du questionnaire, e-mails des clients compris.","d":"D8"},{"t":"p","x":"Rédaction : assistant IA ; relecture : à faire."}],"defauts":[{"n":"D1","loc":"Section 1 : « Le Concurrent B a déployé la clé mobile dans tous ses hôtels », avec pour source « communiqué de presse d'il y a 18 mois annonçant un projet »","def":"Une annonce vieille de 18 mois est présentée comme un déploiement, alors que la source citée juste en dessous ne parle que d'un projet.","crit":"La trouvaille désigne la phrase sur le Concurrent B, ET dit que la source n'annonce qu'un projet, qu'elle date de 18 mois, ou que le déploiement n'est pas démontré.","mod":"M1","h1":"Relis la section 1 : que dit exactement la source de la phrase sur le Concurrent B ?","h2":"Un communiqué qui annonce un projet prouve-t-il un déploiement « dans tous ses hôtels » ?","exp":"Une case de veille ne dit pas plus que sa source. Une annonce n'est pas un déploiement, encore moins 18 mois plus tard, sans confirmation."},{"n":"D2","loc":"Section 2 : « Les clients veulent avant tout le départ express : 17 réponses sur 60 », alors que la note précise « dont 36 de LYS-03, surtout des séjours d'affaires » et que le thème cité est « l'attente au comptoir (17 réponses) »","def":"Un échantillon dominé par LYS-03 et par les séjours d'affaires devient « les clients », et un besoin (ne pas attendre) devient une solution (le départ express).","crit":"La trouvaille désigne cette phrase, ET dit que l'échantillon est déséquilibré (LYS-03, séjours d'affaires), ou que les 17 réponses parlent de l'attente et non du départ express.","mod":"M2","h1":"Relis la section 2 : d'où viennent les 60 réponses ?","h2":"Les 17 réponses parlent-elles du départ express, ou de l'attente ?","exp":"On dit d'où viennent les réponses avant de parler « des clients ». Et une opportunité est un besoin avec sa preuve : les 17 réponses citent l'attente, pas une solution."},{"n":"D3","loc":"Section 3 : « KR4.1 : livrer le départ express sur les trois hôtels pilotes »","def":"Un livrable est présenté comme un résultat clé : il se coche le jour de la mise en production, même si personne ne s'en sert.","crit":"La trouvaille désigne KR4.1, ET dit que c'est un livrable ou une tâche, pas un effet mesurable chez les clients ou dans les hôtels.","mod":"M3","h1":"Relis la section 3 : que mesure chacun des deux résultats clés ?","h2":"KR4.1 mesure-t-il un effet chez les clients, ou une livraison ?","exp":"Un résultat clé mesure un effet, avec une source, une période et un calcul. KR4.2, juste en dessous, a la forme attendue."},{"n":"D4","loc":"Section 4 : « Gain : 47,6 h par mois × 25 € de l'heure × 12 = 14 280 € par an », repris en section 7 (« voir le gain calculé en section 4 »), alors que « coût horaire de la réception : non fourni »","def":"Une valeur inventée (25 € de l'heure) sert à annoncer un gain en euros, alors que la note dit elle-même que le coût horaire n'est pas fourni.","crit":"La trouvaille désigne ce calcul ou sa reprise en section 7, ET dit que les 25 € de l'heure ne viennent d'aucune source, ou que le coût horaire est « non fourni ».","mod":"M4","h1":"Relis la section 4 : d'où vient chaque nombre du calcul du gain ?","h2":"Que dit la dernière ligne de la section sur le coût horaire ?","exp":"Un business case n'utilise que des valeurs qui ont une source. Sans coût horaire, la conclusion se dit en heures, et on demande le chiffre à la direction financière."},{"n":"D5","loc":"Section 5 : « Sprint 2 : I4 et I8 avec l'équipe Amarre », alors que « L'équipe Amarre est disponible un seul sprint et ne peut prendre qu'un des deux »","def":"La même disponibilité de l'équipe Amarre est comptée deux fois : la feuille de route prévoit deux sujets là où la capacité n'en permet qu'un.","crit":"La trouvaille désigne le sprint 2, ET dit que l'équipe Amarre ne peut prendre qu'un des deux sujets, ou que sa capacité est comptée deux fois.","mod":"M5","h1":"Relis la section 5 : combien de sujets l'équipe Amarre peut-elle prendre ?","h2":"Combien de sujets le sprint 2 lui confie-t-il ?","exp":"Un scénario tient dans la capacité de chaque équipe dont il dépend. Ici, il faut choisir entre I4 et I8, et dire lequel attend."},{"n":"D6","loc":"Section 6 : « Le pilote est un succès : 24 % de départs express », alors que plus bas figurent « 574 départs express sur 3 365 départs » et des litiges « de 1 à 5 par semaine »","def":"La meilleure semaine est présentée comme le résultat du pilote (17,1 % sur l'ensemble), et la hausse des litiges, un garde-fou dégradé, est ignorée.","crit":"La trouvaille désigne « succès » ou « 24 % », ET dit que le pilote fait 17,1 % (574 sur 3 365), que 24 % est la dernière semaine, ou que les litiges ont augmenté.","mod":"M6","h1":"Relis la section 6 : sur quelle période les 24 % sont-ils calculés ?","h2":"Que donnent 574 départs express sur 3 365 ? Et que font les litiges ?","exp":"Une part se calcule sur toute la période et sur le bon dénominateur : 17,1 %. Et un garde-fou dégradé compte autant que l'objectif : « succès » ne tient pas."},{"n":"D7","loc":"Section 7 : « le départ tardif sera livré au prochain trimestre, sans risque », alors que « État de LAN-101 (départ tardif) : toujours à spécifier »","def":"Une date est promise pour calmer une objection, sur un sujet qui n'est pas spécifié : l'inconnue est cachée.","crit":"La trouvaille désigne cette réponse, ET dit que LAN-101 n'est pas spécifié, qu'on ne peut pas promettre de date, ou que le risque est caché.","mod":"M7","h1":"Relis la section 7 : que promet la réponse à la direction des opérations ?","h2":"Où en est LAN-101, d'après la ligne suivante ?","exp":"On ne promet pas une date pour calmer une objection. On dit ce qu'on sait (la règle n'est pas écrite), ce qu'on fait (la spécifier), et quand on pourra donner une date."},{"n":"D8","loc":"Section 8 : « la fiche de contexte de l'an dernier, sans date de revue, et l'export complet du questionnaire, e-mails des clients compris »","def":"Un contexte périmé a été donné à l'IA, et des données personnelles lui ont été transmises sans nécessité.","crit":"La trouvaille désigne le contexte fourni, ET dit que la fiche est périmée (l'an dernier, sans date de revue), ou que des données personnelles (les e-mails) ont été transmises.","mod":"M8","h1":"Relis la section 8 : qu'a-t-on donné à l'IA pour rédiger la note ?","h2":"De quoi l'IA avait-elle besoin, et qu'a-t-elle reçu en trop ?","exp":"L'IA travaille avec le contexte qu'on lui donne : une fiche à jour, sourcée et datée. Et elle n'a besoin ni des e-mails des clients, ni du détail des réponses, pour rédiger une note."}]}},"headers":[],"relativePath":"pm/quiz.md","filePath":"pm/quiz.md"}`),m={name:"pm/quiz.md"};function f(x,s,q,h,v,L){const i=n("Etape"),o=n("Livrable"),l=n("Quiz",!0),u=n("Module");return p(),c("div",null,[t(u,null,{default:r(()=>[t(i,{cle:"qz-situation",titre:"La situation"},{default:r(()=>[...s[0]||(s[0]=[e("div",{class:"st-box st-situation"},[e("p",{class:"st-lbl"},"Situation"),e("p",null,[a("Céline a demandé à son assistant IA une "),e("strong",null,"note de décision"),a(" pour la revue du portefeuille Séjour : marché, retours des clients, objectifs, business case, feuille de route, résultats du pilote et réponses aux objections.")]),e("p",null,"Avant la revue, elle te demande de la relire, comme si c'était à toi de la défendre."),e("p",null,"Tout ce dont tu as besoin est dans la note affichée à l'étape suivante. Les chiffres qu'elle contient sont fictifs.")],-1)])]),_:1}),t(i,{cle:"qz-livrable",titre:"Le livrable à auditer"},{default:r(()=>[s[1]||(s[1]=e("p",null,"Lis le livrable en entier. Tu le retrouveras à côté de ta liste de trouvailles à l'étape suivante.",-1)),t(o)]),_:1}),t(i,{cle:"qz-mission",titre:"La mission"},{default:r(()=>[t(l)]),_:1})]),_:1})])}const j=d(m,[["render",f]]);export{b as __pageData,j as default};
